#pragma once

#include <cstdint>
#include <span>
#include <string>
#include <string_view>
#include <vector>

#include "shader/sm_tokens.h"

namespace rvk::shader {

struct SpirvResult {
    std::vector<std::uint32_t> words;
    std::string log;  // compiler messages (errors on failure)
    bool ok() const { return !words.empty(); }
};

// HLSL text generated by shader::toHlsl (or the uber assembly) -> SPIR-V 1.6 for Vulkan 1.3 through the runtime DXC (shader/dxc.h): entry VSMain / PSMain,
// -O1, through the DXC disk cache (shader/dxc.h: keyed by the text, the arguments and DXC's version; WS12). `name` = the shader in diagnostics. Thread-safe.
SpirvResult compileHlsl(Stage stage, std::string_view hlsl, std::string_view name = "translated.hlsl", bool half16 = false);

// The same HLSL text as signed DXIL SM 6.6 for the DX12 backend (container bytes; empty on failure, `log` has the messages).
struct DxilResult {
    std::vector<std::uint8_t> bytes;
    std::string log;
    bool fromCache = false;
    bool ok() const { return !bytes.empty(); }
};
DxilResult compileHlslDxil(Stage stage, std::string_view hlsl, std::string_view name = "translated.hlsl", bool half16 = false, bool refresh = false);

// OpDemoteToHelperInvocation + the OpBranch ending its block -> OpKill (and the capability dropped when none is left); true when the module changed.
// Used for shader modules that run in fast-linked pipeline libraries (frame-ownership.md 16.27: the AMD driver exports demoted lanes of a quad with live
// lanes there when the shader takes derivatives).
bool demoteToKill(std::vector<std::uint32_t>& words);

// OpExecutionMode EarlyFragmentTests on the fragment entry (WS42); true when the module changed.
bool addEarlyFragmentTests(std::vector<std::uint32_t>& words);

// A fragment module with a discard that does not write FragDepth (WS42: the modules that get an early-tests twin).
bool fragmentDiscards(std::span<const std::uint32_t> words);

// Debug info in the SPIR-V DXC produces (config.toml [debug] shader_debug_info, run.ps1 -ShaderDebug): -Zi -Od with OpName / OpLine and the HLSL source text,
// so RenderDoc / PIX show names and source lines and allow stepping through the translated D3D9 shaders, the material shaders and the embedded ones.
// Set before the first compile; part of the SPIR-V cache keys.
void setDebugInfo(bool on);
bool debugInfo();

}  // namespace rvk::shader
